FUNCTION_BLOCK FB_MarineRiser_TensionerRecoil
(* =========================================================================================================
   SYSTEM:       Ultra-Deepwater Marine Drilling Riser Tensioning & Recoil Control System (RCS)
   SUBSYSTEM:    Electro-Hydraulic Tensioner Recoil Damping & Emergency Disconnect Sequence (EDS) Mitigation
   ARCHITECTURE: Triple Modular Redundant (2oo3 TMR) Voting, State-Space Predictive Deceleration (MPC),
                 Dynamic Hydro-Mechanical Kinetic Energy Dissipation, Anti-Plunge BOP Re-Impact Prevention
   STANDARDS:    IEC 61131-3 3rd Ed., API Spec 16F (Marine Drilling Riser Systems), API RP 16Q, ISO 13624-1
   AUTHOR:       Principal Automation Fellow & Cyber-Physical Systems Chair (Lumina AI Swarm)
   CYCLE TIME:   10 ms deterministic execution interval
   ========================================================================================================= *)

VAR_INPUT
    (* --- System Safety and Supervisor Interlocks --- *)
    bSystemEnable           : BOOL;     (* [bool] Master system execution enable interlock *)
    bEDS_Trigger_ChA        : BOOL;     (* [bool] Emergency Disconnect Sequence trigger - Safety Channel A *)
    bEDS_Trigger_ChB        : BOOL;     (* [bool] Emergency Disconnect Sequence trigger - Safety Channel B *)
    bEDS_Trigger_ChC        : BOOL;     (* [bool] Emergency Disconnect Sequence trigger - Safety Channel C (2oo3 architecture) *)

    (* --- Physical Sensors: Triplicated Cylinder Stroke Instrumentation --- *)
    rRiserStroke_m_ChA      : REAL;     (* [m] Telescopic slip-joint / Direct-Acting Tensioner (DAT) stroke - Channel A *)
    rRiserStroke_m_ChB      : REAL;     (* [m] Telescopic slip-joint / Direct-Acting Tensioner (DAT) stroke - Channel B *)
    rRiserStroke_m_ChC      : REAL;     (* [m] Telescopic slip-joint / Direct-Acting Tensioner (DAT) stroke - Channel C *)

    (* --- Kinematics, Dynamics, and Hydraulic Physical Process Variables --- *)
    rRiserVelocity_mps      : REAL;     (* [m/s] Instantaneous vertical velocity of riser slip-joint / DAT cylinders *)
    rRiserAccel_mps2        : REAL;     (* [m/s^2] Moonpool / riser head vertical linear acceleration from MRU *)
    rHydraulicPressure_bar  : REAL;     (* [bar] Main hydraulic accumulator manifold / Air Pressure Vessel (APV) pressure *)
    rRiserTension_kN        : REAL;     (* [kN] Measured total overpull top tension support load across all wireline/DATs *)
    rFlexJointAngle_deg     : REAL;     (* [deg] Subsea Lower Marine Riser Package (LMRP) flex-joint angular deviation *)
    rMudDensity_sg          : REAL;     (* [sg] Specific gravity of active drilling fluid column (e.g. 1.15 to 2.10 sg) *)
    rSeaStateHeaveAmp_m     : REAL;     (* [m] Significant vessel heave amplitude from vessel marine dynamics unit *)

    (* --- Operational Commands and Diagnostic Resets --- *)
    bManualOverrideTrip     : BOOL;     (* [bool] Hardwired console emergency disconnect push-button *)
    bResetFaults            : BOOL;     (* [bool] Supervisory reset for latched fault conditions *)
END_VAR

VAR_OUTPUT
    (* --- Safety Critical Actuator Controls --- *)
    bRecoilActive           : BOOL;     (* [bool] Active recoil deceleration damping mode currently engaged *)
    bDisarmLatchPermissive  : BOOL;     (* [bool] LMRP subsea mechanical hydraulic connector unlock permissive *)
    rRCV_ValveCmd_pct       : REAL;     (* [%] High-speed Recoil Control Valve (RCV) proportional command [0.0..100.0%] *)
    bEmergencyDumpValve     : BOOL;     (* [bool] High-pressure nitrogen/fluid rapid blowdown valve command *)

    (* --- Real-Time Synthesized Engineering Dynamics and Clearance Verification --- *)
    rDampingForce_kN        : REAL;     (* [kN] Calculated instantaneous hydrodynamic throttling counter-force *)
    rPredictedPeakStroke_m  : REAL;     (* [m] State-space predictive peak cylinder stroke displacement *)
    rKineticEnergy_kJ       : REAL;     (* [kJ] Real-time kinetic energy dissipation estimate of riser string *)
    bSafeClearanceAchieved  : BOOL;     (* [bool] Post-disconnect clearance confirmed between LMRP and subsea BOP *)

    (* --- Comprehensive Industrial Telemetry and Diagnostics --- *)
    wSystemStatusWord       : WORD;     (* [hex] Comprehensive FSM operational status and interlock word *)
    wAlarmCode              : WORD;     (* [hex] Active safety fault, sensor discrepancy, and trip code word *)
    wDegradedSensorMask     : WORD;     (* [hex] Bitfield indicating failed or drifting redundant instrumentation *)
END_VAR

VAR
    (* =====================================================================================================
       INTERNAL REGISTERS: 2oo3 TMR VOTING LOGIC & INSTRUMENTATION INTEGRITY
       ===================================================================================================== *)
    bVotedEDS_Trigger       : BOOL := FALSE; (* 2oo3 voted disconnect command *)
    bChA_Fault              : BOOL := FALSE; (* Channel A discrepancy latched fault *)
    bChB_Fault              : BOOL := FALSE; (* Channel B discrepancy latched fault *)
    bChC_Fault              : BOOL := FALSE; (* Channel C discrepancy latched fault *)
    rVotedStroke_m          : REAL := 0.0;   (* Median-selected validated stroke position *)
    rStrokeDiff_AB          : REAL := 0.0;   (* Channel deviation |ChA - ChB| *)
    rStrokeDiff_BC          : REAL := 0.0;   (* Channel deviation |ChB - ChC| *)
    rStrokeDiff_CA          : REAL := 0.0;   (* Channel deviation |ChC - ChA| *)
    tChA_DiscrepTimer       : TON;           (* Discrepancy filter timer Ch A (100 ms debounce) *)
    tChB_DiscrepTimer       : TON;           (* Discrepancy filter timer Ch B (100 ms debounce) *)
    tChC_DiscrepTimer       : TON;           (* Discrepancy filter timer Ch C (100 ms debounce) *)
    bDegradedSensorMode     : BOOL := FALSE; (* True if one stroke channel has drifted/failed *)
    bTotalInstrumentationFail : BOOL := FALSE; (* True if 2 or more channels fail *)

    (* =====================================================================================================
       INTERNAL REGISTERS: STATE-SPACE DISCRETE MODEL PREDICTIVE HORIZON (MPC)
       State Vector: x(k) = [ e_pos(k) (m), v_riser(k) (m/s), p_eff(k) (bar) ]^T
       Discrete Form: x(k+1) = A_d * x(k) + B_d * u(k) + G_d * w(k)
       ===================================================================================================== *)
    rState_x1_PosErr        : REAL := 0.0;   (* State 1: Stroke position error from target [m] *)
    rState_x2_Vel           : REAL := 0.0;   (* State 2: Riser vertical ascent velocity [m/s] *)
    rState_x3_Press         : REAL := 0.0;   (* State 3: Differential hydraulic damping pressure [bar] *)

    (* Discrete Transition Matrix Coefficients (T_s = 0.010 s, Hydro-Mechanical linearized at 120 bar) *)
    cA11 : REAL := 1.0000;  cA12 : REAL := 0.0098;  cA13 : REAL := -0.000015;
    cA21 : REAL := -0.0125; cA22 : REAL := 0.9850;  cA23 : REAL := -0.002850;
    cA31 : REAL := 0.0000;  cA32 : REAL := 0.1420;  cA33 : REAL := 0.945000;

    (* Discrete Input Gain Matrix Coefficients (u = RCV Valve Opening Command [0..100%]) *)
    cB11 : REAL := 0.00005; cB21 : REAL := 0.0182;  cB31 : REAL := -0.354000;

    (* Disturbance / Hydrostatic Buoyancy Coefficients (w = Net Overpull minus Mud Column Weight) *)
    cG1 : REAL := 0.0005;   cG2 : REAL := 0.0981;   cG3 : REAL := 0.0000;

    (* Fast-Predictive Horizon Accumulators (N_p = 10 steps lookahead, 100 ms total lookahead window) *)
    iPredStep               : INT := 0;
    rSim_x1                 : REAL := 0.0;
    rSim_x2                 : REAL := 0.0;
    rSim_x3                 : REAL := 0.0;
    rSim_x1_Next            : REAL := 0.0;
    rSim_x2_Next            : REAL := 0.0;
    rSim_x3_Next            : REAL := 0.0;
    rPeakPredictedStroke    : REAL := 0.0;
    rCandidateValveCmd      : REAL := 0.0;

    (* =====================================================================================================
       INTERNAL REGISTERS: PHYSICAL CONSTANTS & HYDRO-MECHANICAL SIZING
       ===================================================================================================== *)
    rRiserDryMass_kg        : REAL := 380000.0; (* Dry mass of 2500m ultra-deepwater riser string [kg] *)
    rMudColumnMass_kg       : REAL := 125000.0; (* Calculated drilling fluid column internal mass [kg] *)
    rEffectiveMass_kg       : REAL := 505000.0; (* Total dynamic riser inertia including entrained water [kg] *)
    rCylinderArea_m2        : REAL := 0.0825;   (* Total combined DAT cylinder bore area (6-cylinder ring) [m^2] *)
    rFluidDensity_kgpm3     : REAL := 920.0;    (* Anti-wear water-glycol hydraulic fluid density [kg/m^3] *)
    rDischargeCoeff_Cd      : REAL := 0.62;     (* Sharp-edged proportional throttle orifice discharge coefficient *)
    rMaxValveArea_m2        : REAL := 0.0125;   (* Total fully-open RCV flow area [m^2] *)
    rMaxAllowableStroke_m   : REAL := 13.80;    (* Hard physical threshold: moonpool crown collision barrier [m] *)
    rTargetRestStroke_m     : REAL := 4.80;     (* Ideal safe post-disconnect hang-off stroke [m] *)
    rMinClearanceGap_m      : REAL := 3.20;     (* Minimum required separation clearance above BOP [m] *)
    rStrokeSynthetic        : REAL := 0.0;      (* Dead-reckoning stroke estimate during multi-sensor degradation *)

    (* =====================================================================================================
       INTERNAL REGISTERS: MULTI-STAGE FINITE STATE MACHINE (FSM) & DAMPING CONTROLLERS
       ===================================================================================================== *)
    iFSM_State              : INT := 0;         (* Main operational state machine index *)
    iPrevFSM_State          : INT := 0;         (* Historical state register for transition detection *)
    rStrokeRateFiltered     : REAL := 0.0;      (* First-order filtered vertical velocity [m/s] *)
    rNetUpwardForce_kN      : REAL := 0.0;      (* Tension overpull minus submerged riser weight [kN] *)
    rRequiredDamping_kN     : REAL := 0.0;      (* Instantaneous counter-force required by trajectory generator *)
    rCalculatedValveArea_m2 : REAL := 0.0;      (* Sized hydraulic orifice area via Bernoulli equation [m^2] *)
    rOrificePressureDiff_Pa : REAL := 0.0;      (* Pressure drop across RCV hydraulic manifold [Pa] *)
    rFlowVelocity_mps       : REAL := 0.0;      (* Volumetric flow velocity through control choke [m/s] *)

    (* Anti-Plunge / Re-Strike Mitigation Registers *)
    bAntiPlungeEngaged      : BOOL := FALSE;    (* Latched flag when riser ascent halts and reversal looms *)
    rAntiPlungeBrakeHold_pct: REAL := 8.5;       (* Minimum holding orifice command to damp downward plunge [%] *)
    rPeakStrokeAchieved_m   : REAL := 0.0;      (* Max stroke reached during current recoil event [m] *)

    (* Timers for Deterministic Phase Transitions *)
    tRecoilPhaseTimer       : TON;              (* Active recoil window duration timer *)
    tLMRP_ClearanceTimer    : TON;              (* Physical connector unlatch clearance confirmation timer *)
    tHangOffStabilizeTimer  : TON;              (* Post-recoil hydro-pneumatic equilibrium stabilization timer *)
    tEDS_ArmTimeout         : TON;              (* Timeout window for pre-charging RCVs during EDS arming *)

    (* Fault Latches and Bitmasks *)
    bOverStrokeWarning      : BOOL := FALSE;
    bOverStrokeTrip         : BOOL := FALSE;
    bFlexJointAngleExceeded : BOOL := FALSE;
    bHydraulicPressureLow   : BOOL := FALSE;
END_VAR

(* =========================================================================================================
   EXECUTION CYCLE START
   ========================================================================================================= *)

(* ---------------------------------------------------------------------------------------------------------
   STAGE 1: 2oo3 TRIPLE MODULAR REDUNDANT (TMR) SAFETY VOTING & FAULT DETECTION
   Compliant with IEC 61508 / IEC 61511 SIL-3 architecture for safety-critical subsea disconnect
   --------------------------------------------------------------------------------------------------------- *)
(* Boolean 2oo3 Voting for Emergency Disconnect Sequence Command *)
bVotedEDS_Trigger := (bEDS_Trigger_ChA AND bEDS_Trigger_ChB) OR
                     (bEDS_Trigger_ChB AND bEDS_Trigger_ChC) OR
                     (bEDS_Trigger_ChA AND bEDS_Trigger_ChC) OR
                     bManualOverrideTrip;

(* Compute Inter-Channel Discrepancies on Triplicated Stroke Transducers (Threshold = 0.35 m) *)
rStrokeDiff_AB := ABS(rRiserStroke_m_ChA - rRiserStroke_m_ChB);
rStrokeDiff_BC := ABS(rRiserStroke_m_ChB - rRiserStroke_m_ChC);
rStrokeDiff_CA := ABS(rRiserStroke_m_ChC - rRiserStroke_m_ChA);

(* Channel Discrepancy Debounce Timers (100 ms persistence required to flag hardware failure) *)
tChA_DiscrepTimer(IN := (rStrokeDiff_AB > 0.35) AND (rStrokeDiff_CA > 0.35), PT := T#100MS);
tChB_DiscrepTimer(IN := (rStrokeDiff_AB > 0.35) AND (rStrokeDiff_BC > 0.35), PT := T#100MS);
tChC_DiscrepTimer(IN := (rStrokeDiff_BC > 0.35) AND (rStrokeDiff_CA > 0.35), PT := T#100MS);

IF tChA_DiscrepTimer.Q THEN bChA_Fault := TRUE; END_IF;
IF tChB_DiscrepTimer.Q THEN bChB_Fault := TRUE; END_IF;
IF tChC_DiscrepTimer.Q THEN bChC_Fault := TRUE; END_IF;

(* Fault Reset Handling *)
IF bResetFaults THEN
    bChA_Fault := FALSE;
    bChB_Fault := FALSE;
    bChC_Fault := FALSE;
    bOverStrokeWarning := FALSE;
    bOverStrokeTrip := FALSE;
    wAlarmCode := 16#0000;
END_IF;

(* Graceful Degradation Median Selection / Fallback Voting *)
IF NOT bChA_Fault AND NOT bChB_Fault AND NOT bChC_Fault THEN
    (* All 3 channels healthy: Classic 3-channel Median Selector *)
    IF ((rRiserStroke_m_ChA >= rRiserStroke_m_ChB) AND (rRiserStroke_m_ChA <= rRiserStroke_m_ChC)) OR
       ((rRiserStroke_m_ChA >= rRiserStroke_m_ChC) AND (rRiserStroke_m_ChA <= rRiserStroke_m_ChB)) THEN
        rVotedStroke_m := rRiserStroke_m_ChA;
    ELSIF ((rRiserStroke_m_ChB >= rRiserStroke_m_ChA) AND (rRiserStroke_m_ChB <= rRiserStroke_m_ChC)) OR
          ((rRiserStroke_m_ChB >= rRiserStroke_m_ChC) AND (rRiserStroke_m_ChB <= rRiserStroke_m_ChA)) THEN
        rVotedStroke_m := rRiserStroke_m_ChB;
    ELSE
        rVotedStroke_m := rRiserStroke_m_ChC;
    END_IF;
    bDegradedSensorMode := FALSE;
    bTotalInstrumentationFail := FALSE;
ELSIF bChA_Fault AND NOT bChB_Fault AND NOT bChC_Fault THEN
    (* Channel A failed: 1oo2 average of B and C *)
    rVotedStroke_m := (rRiserStroke_m_ChB + rRiserStroke_m_ChC) * 0.5;
    bDegradedSensorMode := TRUE;
ELSIF bChB_Fault AND NOT bChA_Fault AND NOT bChC_Fault THEN
    (* Channel B failed: 1oo2 average of A and C *)
    rVotedStroke_m := (rRiserStroke_m_ChA + rRiserStroke_m_ChC) * 0.5;
    bDegradedSensorMode := TRUE;
ELSIF bChC_Fault AND NOT bChA_Fault AND NOT bChB_Fault THEN
    (* Channel C failed: 1oo2 average of A and B *)
    rVotedStroke_m := (rRiserStroke_m_ChA + rRiserStroke_m_ChB) * 0.5;
    bDegradedSensorMode := TRUE;
ELSE
    (* Multiple sensor failure: Fallback to Dead-Reckoning Integration using velocity *)
    bTotalInstrumentationFail := TRUE;
    rStrokeSynthetic := rStrokeSynthetic + (rRiserVelocity_mps * 0.010);
    rVotedStroke_m := rStrokeSynthetic;
END_IF;

(* ---------------------------------------------------------------------------------------------------------
   STAGE 2: CYBER-PHYSICAL MODELING & STATE ESTIMATION
   Continuous-to-discrete physics: Mass-Spring-Damper with Variable Mud Weight
   --------------------------------------------------------------------------------------------------------- *)
(* Dynamic Mud Column and Effective Riser Mass Calculation *)
rMudColumnMass_kg := 2500.0 * 3.14159 * (0.2413 * 0.2413) * (rMudDensity_sg * 1000.0);
IF rMudColumnMass_kg < 50000.0 THEN rMudColumnMass_kg := 50000.0; END_IF;
rEffectiveMass_kg := rRiserDryMass_kg + rMudColumnMass_kg;

(* Velocity Filtering: 1st-Order Lag (Cutoff frequency = 15 Hz) *)
rStrokeRateFiltered := (0.85 * rStrokeRateFiltered) + (0.15 * rRiserVelocity_mps);

(* Riser Kinetic Energy in Moonpool Reference Frame: E_k = 0.5 * m * v^2 [kJ] *)
rKineticEnergy_kJ := 0.5 * (rEffectiveMass_kg / 1000.0) * (rStrokeRateFiltered * rStrokeRateFiltered);

(* Net Upward Overpull Force: Tension minus Submerged Riser Weight [kN] *)
rNetUpwardForce_kN := rRiserTension_kN - ((rEffectiveMass_kg * 9.80665) / 1000.0);

(* Hydraulic Damping Counter-Force Synthesis based on Orifice Equation *)
(* DeltaP = 0.5 * rho * (Q / (Cd * A_v))^2, Force = DeltaP * CylinderArea *)
IF rRCV_ValveCmd_pct > 1.0 THEN
    rCalculatedValveArea_m2 := (rRCV_ValveCmd_pct / 100.0) * rMaxValveArea_m2;
    rFlowVelocity_mps := (ABS(rStrokeRateFiltered) * rCylinderArea_m2) / (rDischargeCoeff_Cd * rCalculatedValveArea_m2);
    rOrificePressureDiff_Pa := 0.5 * rFluidDensity_kgpm3 * (rFlowVelocity_mps * rFlowVelocity_mps);
    rDampingForce_kN := (rOrificePressureDiff_Pa * rCylinderArea_m2) / 1000.0;
ELSE
    (* Valve closed: Maximum hydrostatic hydraulic block limit *)
    rDampingForce_kN := (rHydraulicPressure_bar * 100.0 * rCylinderArea_m2);
END_IF;

(* Update State-Space State Vector *)
rState_x1_PosErr := rVotedStroke_m - rTargetRestStroke_m;
rState_x2_Vel    := rStrokeRateFiltered;
rState_x3_Press  := (rHydraulicPressure_bar - 120.0);

(* ---------------------------------------------------------------------------------------------------------
   STAGE 3: FAST MODEL PREDICTIVE CONTROL (MPC) RECOIL PEAK STROKE HORIZON
   Simulates 10-step forward horizon (100 ms) to predict peak telescopic stroke displacement
   --------------------------------------------------------------------------------------------------------- *)
rSim_x1 := rState_x1_PosErr;
rSim_x2 := rState_x2_Vel;
rSim_x3 := rState_x3_Press;
rPeakPredictedStroke := rVotedStroke_m;
rCandidateValveCmd := rRCV_ValveCmd_pct;

FOR iPredStep := 1 TO 10 DO
    (* State Prediction Equation: x_next = A * x + B * u + G * w *)
    rSim_x1_Next := (cA11 * rSim_x1) + (cA12 * rSim_x2) + (cA13 * rSim_x3) + (cB11 * rCandidateValveCmd) + (cG1 * (rNetUpwardForce_kN / 1000.0));
    rSim_x2_Next := (cA21 * rSim_x1) + (cA22 * rSim_x2) + (cA23 * rSim_x3) + (cB21 * rCandidateValveCmd) + (cG2 * (rNetUpwardForce_kN / 1000.0));
    rSim_x3_Next := (cA31 * rSim_x1) + (cA32 * rSim_x2) + (cA33 * rSim_x3) + (cB31 * rCandidateValveCmd);

    rSim_x1 := rSim_x1_Next;
    rSim_x2 := rSim_x2_Next;
    rSim_x3 := rSim_x3_Next;

    IF (rTargetRestStroke_m + rSim_x1) > rPeakPredictedStroke THEN
        rPeakPredictedStroke := rTargetRestStroke_m + rSim_x1;
    END_IF;
END_FOR;

rPredictedPeakStroke_m := rPeakPredictedStroke;

(* ---------------------------------------------------------------------------------------------------------
   STAGE 4: SAFETY INTERLOCK ALARM TREE EVALUATION
   --------------------------------------------------------------------------------------------------------- *)
IF rVotedStroke_m >= 12.50 THEN
    bOverStrokeWarning := TRUE;
    wAlarmCode := wAlarmCode OR 16#0001; (* Warning: 90% Slip joint extension *)
END_IF;

IF rVotedStroke_m >= rMaxAllowableStroke_m THEN
    bOverStrokeTrip := TRUE;
    wAlarmCode := wAlarmCode OR 16#0002; (* Critical: Hard overstroke boundary *)
END_IF;

IF ABS(rFlexJointAngle_deg) > 7.50 THEN
    bFlexJointAngleExceeded := TRUE;
    wAlarmCode := wAlarmCode OR 16#0004; (* Flex joint angle exceedance warning *)
END_IF;

IF rHydraulicPressure_bar < 95.0 THEN
    bHydraulicPressureLow := TRUE;
    wAlarmCode := wAlarmCode OR 16#0008; (* APV hydraulic pre-charge below safe envelope *)
END_IF;

IF bTotalInstrumentationFail THEN
    wAlarmCode := wAlarmCode OR 16#0010; (* Total TMR stroke sensor breakdown *)
END_IF;

(* Degraded Sensor Bitmask Encoding *)
wDegradedSensorMask := 16#0000;
IF bChA_Fault THEN wDegradedSensorMask := wDegradedSensorMask OR 16#0001; END_IF;
IF bChB_Fault THEN wDegradedSensorMask := wDegradedSensorMask OR 16#0002; END_IF;
IF bChC_Fault THEN wDegradedSensorMask := wDegradedSensorMask OR 16#0004; END_IF;

(* ---------------------------------------------------------------------------------------------------------
   STAGE 5: MULTI-STAGE FINITE STATE MACHINE (FSM)
   Deterministic sequencing of Tensioner Recoil Damping and Emergency Disconnect
   --------------------------------------------------------------------------------------------------------- *)
IF NOT bSystemEnable THEN
    iFSM_State := 0; (* System disabled: default to standby *)
END_IF;

CASE iFSM_State OF
    0: (* STATE 0: IDLE_STANDBY - System initialized, awaiting master enable *)
        bRecoilActive           := FALSE;
        bDisarmLatchPermissive  := FALSE;
        rRCV_ValveCmd_pct       := 100.0; (* Recoil valves fully open for normal flow *)
        bEmergencyDumpValve     := FALSE;
        bSafeClearanceAchieved  := FALSE;
        bAntiPlungeEngaged      := FALSE;
        rPeakStrokeAchieved_m   := 0.0;

        tRecoilPhaseTimer(IN := FALSE, PT := T#5S);
        tLMRP_ClearanceTimer(IN := FALSE, PT := T#3S);
        tHangOffStabilizeTimer(IN := FALSE, PT := T#10S);
        tEDS_ArmTimeout(IN := FALSE, PT := T#2S);

        IF bSystemEnable AND NOT bOverStrokeTrip THEN
            iFSM_State := 10; (* Transition to Normal Active Tensioning *)
        END_IF;

    10: (* STATE 10: TENSIONING_NORMAL - Active Heave Compensation / Normal Drilling *)
        bRecoilActive           := FALSE;
        bDisarmLatchPermissive  := FALSE;
        rRCV_ValveCmd_pct       := 100.0; (* Full unrestricted hydraulic communication with APVs *)
        bEmergencyDumpValve     := FALSE;
        bSafeClearanceAchieved  := FALSE;
        rPeakStrokeAchieved_m   := rVotedStroke_m;

        (* Monitor for Emergency Disconnect Initiation *)
        IF bVotedEDS_Trigger THEN
            iFSM_State := 20; (* Advance to EDS Pre-charge & Arming *)
        ELSIF bOverStrokeTrip THEN
            iFSM_State := 99; (* Uncontrolled overstroke safety trip *)
        END_IF;

    20: (* STATE 20: EDS_ARMED_PRE_RELEASE - Subsea connector pre-arm, pre-positioning RCVs *)
        bRecoilActive           := TRUE;
        bDisarmLatchPermissive  := FALSE;
        bEmergencyDumpValve     := FALSE;

        (* Rapidly throttle RCV to 45% pre-charge orifice to prepare for sudden acceleration shock *)
        rRCV_ValveCmd_pct       := 45.0;

        tEDS_ArmTimeout(IN := TRUE, PT := T#200MS);

        (* Once RCV pre-charge position verified and hydraulic pressure nominal, authorize LMRP unlatch *)
        IF tEDS_ArmTimeout.Q AND NOT bHydraulicPressureLow THEN
            bDisarmLatchPermissive := TRUE; (* Permissive granted to subsea electro-hydraulic multiplex pod *)
            tEDS_ArmTimeout(IN := FALSE);
            iFSM_State := 30; (* Advance directly to High-Kinetic Recoil Damping *)
        ELSIF NOT bVotedEDS_Trigger THEN
            (* Operator aborted EDS sequence before unlatch execution *)
            tEDS_ArmTimeout(IN := FALSE);
            iFSM_State := 10;
        END_IF;

    30: (* STATE 30: RECOIL_DAMPING_PRIMARY - Violent riser upward acceleration phase *)
        bRecoilActive           := TRUE;
        bDisarmLatchPermissive  := TRUE;
        bEmergencyDumpValve     := FALSE;

        tRecoilPhaseTimer(IN := TRUE, PT := T#4S);
        tLMRP_ClearanceTimer(IN := TRUE, PT := T#1500MS);

        (* Track Maximum Recorded Stroke *)
        IF rVotedStroke_m > rPeakStrokeAchieved_m THEN
            rPeakStrokeAchieved_m := rVotedStroke_m;
        END_IF;

        (* Check LMRP Separation Clearance from Subsea BOP Stack *)
        IF tLMRP_ClearanceTimer.Q AND (rVotedStroke_m >= (rTargetRestStroke_m - 0.50)) THEN
            bSafeClearanceAchieved := TRUE;
        END_IF;

        (* Active MPC Damping Law: Adjust RCV proportional opening to arrest upward velocity *)
        (* Target deceleration trajectory: limit upward speed proportionally as stroke nears moonpool limit *)
        IF rStrokeRateFiltered > 0.20 THEN
            (* Riser is accelerating/moving upward rapidly *)
            IF rPredictedPeakStroke_m > 12.00 THEN
                (* Aggressive hydro-braking: Throttle RCV down towards 10% *)
                rRCV_ValveCmd_pct := 10.0 + (13.80 - rPredictedPeakStroke_m) * 15.0;
                IF rRCV_ValveCmd_pct < 4.0 THEN rRCV_ValveCmd_pct := 4.0; END_IF;
            ELSE
                (* Smooth dynamic deceleration based on kinetic energy dissipation *)
                rRCV_ValveCmd_pct := 30.0 - (rKineticEnergy_kJ * 0.015);
                IF rRCV_ValveCmd_pct < 12.0 THEN rRCV_ValveCmd_pct := 12.0; END_IF;
                IF rRCV_ValveCmd_pct > 65.0 THEN rRCV_ValveCmd_pct := 65.0; END_IF;
            END_IF;
        ELSE
            (* Ascent velocity has halted; riser is reaching peak extension *)
            iFSM_State := 40; (* Immediately enter anti-plunge mitigation to stop downward crash *)
        END_IF;

        (* Safety Watchdog: If primary recoil persists past timeout, transition to settling *)
        IF tRecoilPhaseTimer.Q THEN
            iFSM_State := 40;
        END_IF;

    40: (* STATE 40: ANTI_PLUNGE_DECEL - Prevent downward plunge and re-strike onto subsea BOP *)
        bRecoilActive           := TRUE;
        bDisarmLatchPermissive  := TRUE;
        bAntiPlungeEngaged      := TRUE;

        tRecoilPhaseTimer(IN := FALSE);

        (* If riser begins downward descent (negative velocity), choke RCV to create hydraulic lock *)
        IF rStrokeRateFiltered < -0.05 THEN
            (* Impose high hydraulic backpressure to arrest downward free-fall *)
            rRCV_ValveCmd_pct := rAntiPlungeBrakeHold_pct;
        ELSE
            (* Gentle settling throttling to bring riser to rest stroke *)
            rRCV_ValveCmd_pct := 22.0 + (rVotedStroke_m - rTargetRestStroke_m) * 8.0;
            IF rRCV_ValveCmd_pct < 8.0 THEN rRCV_ValveCmd_pct := 8.0; END_IF;
            IF rRCV_ValveCmd_pct > 35.0 THEN rRCV_ValveCmd_pct := 35.0; END_IF;
        END_IF;

        (* Check for velocity stabilization near zero and acceptable stroke *)
        tHangOffStabilizeTimer(IN := (ABS(rStrokeRateFiltered) < 0.08) AND (rVotedStroke_m < 8.0), PT := T#2500MS);

        IF tHangOffStabilizeTimer.Q THEN
            tHangOffStabilizeTimer(IN := FALSE);
            iFSM_State := 50; (* Transition to Post-Disconnect Controlled Hang-Off *)
        END_IF;

    50: (* STATE 50: POST_DISCONNECT_HANG - Safe hang-off mode in moonpool gimbal/spider *)
        bRecoilActive           := FALSE;
        bDisarmLatchPermissive  := TRUE;
        bSafeClearanceAchieved  := TRUE;
        bAntiPlungeEngaged      := FALSE;

        (* Lock RCVs in position-holding hydrostatic balance *)
        rRCV_ValveCmd_pct       := 15.0;
        bEmergencyDumpValve     := FALSE;

        (* System remains in hang-off mode until operator initiates surface retrieval or reset *)
        IF NOT bVotedEDS_Trigger AND bResetFaults THEN
            iFSM_State := 0; (* Return to Standby *)
        END_IF;

    99: (* STATE 99: FAULT_SAFE_HOLD - Emergency hydraulic lock & pressure relief *)
        bRecoilActive           := FALSE;
        bDisarmLatchPermissive  := FALSE;
        rRCV_ValveCmd_pct       := 0.0; (* Full hydraulic lock to halt all cylinder motion *)
        bEmergencyDumpValve     := bOverStrokeTrip; (* Vent APVs if mechanical overstroke limit breached *)

        (* Latched fault state: Requires deliberate operator reset with all interlocks healthy *)
        IF bResetFaults AND NOT bOverStrokeTrip AND (rVotedStroke_m < 12.0) THEN
            iFSM_State := 0;
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------
   STAGE 6: TELEMETRY & SYSTEM STATUS WORD ENCODING
   --------------------------------------------------------------------------------------------------------- *)
(* Status Word Structure:
   Bits 0-3: FSM State (0..99)
   Bit 4: Recoil Active
   Bit 5: Disarm Latch Permissive
   Bit 6: Safe Clearance Achieved
   Bit 7: Anti-Plunge Active
   Bit 8: Degraded Sensor Mode (1 channel down)
   Bit 9: Total Sensor Breakdown (2+ channels down)
   Bit 10: Overstroke Warning Active
   Bit 11: Emergency Dump Valve Energized
   Bit 12: 2oo3 Disconnect Trigger Latched
*)
wSystemStatusWord := INT_TO_WORD(iFSM_State AND 16#000F);
IF bRecoilActive           THEN wSystemStatusWord := wSystemStatusWord OR 16#0010; END_IF;
IF bDisarmLatchPermissive  THEN wSystemStatusWord := wSystemStatusWord OR 16#0020; END_IF;
IF bSafeClearanceAchieved  THEN wSystemStatusWord := wSystemStatusWord OR 16#0040; END_IF;
IF bAntiPlungeEngaged      THEN wSystemStatusWord := wSystemStatusWord OR 16#0080; END_IF;
IF bDegradedSensorMode     THEN wSystemStatusWord := wSystemStatusWord OR 16#0100; END_IF;
IF bTotalInstrumentationFail THEN wSystemStatusWord := wSystemStatusWord OR 16#0200; END_IF;
IF bOverStrokeWarning      THEN wSystemStatusWord := wSystemStatusWord OR 16#0400; END_IF;
IF bEmergencyDumpValve     THEN wSystemStatusWord := wSystemStatusWord OR 16#0800; END_IF;
IF bVotedEDS_Trigger       THEN wSystemStatusWord := wSystemStatusWord OR 16#1000; END_IF;

END_FUNCTION_BLOCK
